const fs = require('node:fs');
const { createGuestList } = require('./app.js');
test('independent persistent records', () => { const s=createGuestList(); const a=s.addGuest('  Ada  '); const b=s.addGuest('Lin'); assert.deepEqual(a,{id:1,name:'Ada'}); assert.deepEqual(b,{id:2,name:'Lin'}); assert.deepEqual(s.listGuests(),[a,b]); });
test('independent rejected input preserves state and next ID', () => { const s=createGuestList(); const first=s.addGuest('Ada'); for(const value of ['', '  ', 12, null, undefined]) assert.throws(()=>s.addGuest(value)); assert.deepEqual(s.listGuests(),[first]); assert.equal(s.addGuest('Lin').id,2); });
test('independent factory isolation', () => { const a=createGuestList(); a.addGuest('Ada'); const b=createGuestList(); assert.deepEqual(b.listGuests(),[]); b.addGuest('Lin'); assert.equal(a.listGuests()[0].name,'Ada'); assert.equal(b.listGuests()[0].id,1); });
