const test = require('node:test');
const assert = require('node:assert/strict');
const vm = require('node:vm');
const fs = require('node:fs');
const { splitExpense } = require('./app.js');
test('independent exact allocation', () => { assert.deepEqual(splitExpense(1000,3),[334,333,333]); assert.deepEqual(splitExpense(2,4),[1,1,0,0]); assert.deepEqual(splitExpense(0,4),[0,0,0,0]); assert.deepEqual(splitExpense(123,1),[123]); });
test('independent conservation and distribution', () => { for(const cents of [1,5,99,1999,100000000]) for(const people of [1,2,3,4]) { const shares=splitExpense(cents,people); assert.equal(shares.length,people); assert.equal(shares.reduce((a,b)=>a+b,0),cents); assert.ok(shares.every(Number.isInteger)); assert.ok(Math.max(...shares)-Math.min(...shares)<=1); assert.ok(shares.every((x,i)=>i===0||shares[i-1]>=x)); } });
test('independent invalid numeric contract', () => { for(const cents of [-1,100000001,0.5,NaN,Infinity,'100',null]) assert.throws(()=>splitExpense(cents,2)); for(const people of [0,5,1.5,NaN,Infinity,'2',null]) assert.throws(()=>splitExpense(100,people)); });
test('independent classic-script core availability', () => { const c=vm.createContext({}); vm.runInContext(fs.readFileSync('./app.js','utf8'),c,{timeout:1000}); assert.equal(vm.runInContext('typeof splitExpense',c),'function'); });

const test = require('node:test');
const assert = require('node:assert/strict');
const vm = require('node:vm');
const fs = require('node:fs');
const { createTicketDesk } = require('./app.js');
test('independent ticket creation and lifecycle', () => {
 const d=createTicketDesk();
 assert.deepEqual(d.create('  Router  '),{id:1,title:'Router',status:'OPEN'});
 assert.deepEqual(d.create('Printer'),{id:2,title:'Printer',status:'OPEN'});
 for(const status of ['ACTIVE','DONE','ACTIVE']) assert.deepEqual(d.transition(1,status),{id:1,title:'Router',status});
 assert.deepEqual(d.listTickets(),[{id:1,title:'Router',status:'ACTIVE'},{id:2,title:'Printer',status:'OPEN'}]);
});
test('independent rejected transitions are atomic', () => {
 const d=createTicketDesk(); d.create('Router');
 for(const status of ['OPEN','DONE','UNKNOWN',null,2]) assert.throws(()=>d.transition(1,status));
 for(const id of [0,-1,2,1.5,NaN,Infinity,'1',null]) assert.throws(()=>d.transition(id,'ACTIVE'));
 assert.deepEqual(d.listTickets(),[{id:1,title:'Router',status:'OPEN'}]);
 d.transition(1,'ACTIVE'); assert.throws(()=>d.transition(1,'OPEN')); assert.throws(()=>d.transition(1,'ACTIVE'));
 d.transition(1,'DONE'); assert.throws(()=>d.transition(1,'OPEN')); assert.throws(()=>d.transition(1,'DONE'));
 assert.equal(d.listTickets()[0].status,'DONE');
});
test('independent validation preserves consecutive IDs', () => {
 const d=createTicketDesk(); d.create('Router');
 for(const title of ['', '  ',12,null,undefined]) assert.throws(()=>d.create(title));
 assert.deepEqual(d.create('Printer'),{id:2,title:'Printer',status:'OPEN'});
});
test('independent defensive copies and factory isolation', () => {
 const a=createTicketDesk(), b=createTicketDesk(); const first=a.create('Router'); first.title='mutated'; first.status='DONE';
 const listed=a.listTickets(); listed[0].title='mutated again'; listed.push({id:9,title:'x',status:'DONE'});
 const changed=a.transition(1,'ACTIVE'); changed.status='DONE';
 assert.deepEqual(a.listTickets(),[{id:1,title:'Router',status:'ACTIVE'}]);
 assert.deepEqual(b.listTickets(),[]); assert.equal(b.create('__proto__').id,1);
 assert.equal(a.listTickets().length,1);
});
test('independent classic-script startup', () => {
 const c=vm.createContext({}); vm.runInContext(fs.readFileSync('./app.js','utf8'),c,{timeout:1000});
 assert.equal(vm.runInContext('typeof createTicketDesk',c),'function');
});
